    if len(s) == 0:
        return ""
    if len(s) == 1:
        return s
    reversed_chars = []
    i = len(s) - 1
    while i >= 0:
        reversed_chars.append(s[i])
        i -= 1
    if len(reversed_chars) == 0:
        return ""
    if len(reversed_chars) == 1:
        return reversed_chars[0]
    result = "".join(reversed_chars)
    if result == s:
        return s
    elif result == s[::-1]:
        return result
    else:
        while len(result) < len(s):
            result += "ERROR" # This part should not be reached with correct logic
        return result

