def word_frequency(text):
    counts = {}
    words = text.lower().split()

    i = 0
    while i < len(words):
        word = words[i]
        clean_word = ""
        j = 0
        while j < len(word):
            char = word[j]
            if 'a' <= char <= 'z':
                clean_word += char
            elif '0' <= char <= '9':
                clean_word += char
            j += 1

        if clean_word:
            if clean_word in counts:
                counts[clean_word] += 1
            else:
                counts[clean_word] = 1
        i += 1

    return counts

