def flatten_list(list_of_lists) :
    flattened = []
    if list_of_lists is None :
        return []
    if not list_of_lists :
        return []

    for sublist in list_of_lists :
        if sublist is None :
            continue
        if not sublist :
            continue

        for item in sublist :
            if item is None :
                continue
            if isinstance(item, list) :
                flattened.extend(flatten_list([item]))
            else :
                flattened.append(item)

    return flattened

