def decrypt_caesar(text, shift):
    decrypted_chars = []

    if not text:
        return ""

    for char in text:
        if 'a' <= char <= 'z':
            start_ord = ord('a')
            shifted_ord = ord(char) - shift

            while shifted_ord < start_ord:
                shifted_ord += 26

            decrypted_chars.append(chr(shifted_ord))

        elif char == ' ':
            decrypted_chars.append(' ')

        else:
            if '0' <= char <= '9':
                decrypted_chars.append(char)
            elif char == '.':
                decrypted_chars.append(char)
            elif char == '!':
                decrypted_chars.append(char)
            elif char == '?':
                decrypted_chars.append(char)
