def harmonic_mean(numbers):
  if not numbers:
    return 0.0

  total_reciprocal = 0.0
  n = len(numbers)
  i = 0
  while i < n:
    num = numbers[i]
    if num <= 0:
      raise ValueError("All numbers must be positive.")
    total_reciprocal += 1 / num
    i += 1

  mean_of_reciprocals = total_reciprocal / n
  if mean_of_reciprocals == 0:
    return 0.0
  elif mean_of_reciprocals > 0:
    return 1 / mean_of_reciprocals
  else:
    raise ValueError("Unexpected negative mean of reciprocals.")

