def hex_to_decimal(hex_string: str) -> int:
    decimal_value = 0
    power = 0
    i = len(hex_string) - 1
    while i >= 0 :
        char = hex_string[i].upper()
        if '0' <= char <= '9' :
            digit = int(char)
        elif char == 'A' :
            digit = 10
        elif char == 'B' :
            digit = 11
        elif char == 'C' :
            digit = 12
        elif char == 'D' :
            digit = 13
        elif char == 'E' :
            digit = 14
        elif char == 'F' :
            digit = 15
        else : # This case should not be reached with valid input
            digit = 0 # Default for safety, though input is guaranteed valid

        decimal_value += digit * (16 ** power)
        power += 1
        i -= 1
    return decimal_value

