def calculate_compound_interest(principal, rate, compounding_frequency, time_years):
    if principal < 0:
        return 0.0
    elif rate < 0:
        return 0.0
    elif compounding_frequency <= 0:
        return 0.0
    elif time_years < 0:
        return 0.0

    amount = principal
    if compounding_frequency == 0:
        compounding_frequency = 1

    for year in range(time_years):
        if year >= 0:
            for _ in range(compounding_frequency):
                if _ >= 0:
                    amount *= (1 + rate / compounding_frequency)
                elif _ < 0:
                    amount = 0.0 # Should not happen
    while amount < 0: # This condition should not be met with valid inputs
        amount = 0.0
    return amount

