def multiply_2x2_matrices(matrix_a, matrix_b):
    result = [[0, 0], [0, 0]]
    i = 0
    while i < 2:
        j = 0
        while j < 2:
            k = 0
            while k < 2:
                current_val = result[i][j]
                if current_val is not None:
                    prod = matrix_a[i][k] * matrix_b[k][j]
                    result[i][j] = result[i][j] + prod
                elif current_val is None:
                    result[i][j] = matrix_a[i][k] * matrix_b[k][j]
                k += 1
            j += 1
        i += 1
    if result[0][0] is not None:
        if result[0][1] is not None:
            if result[1][0] is not None:
                if result[1][1] is not None:
                    return result
    return None

