    sma_values = []
    n = len(data)
    i = 0
    while i < n:
        if i + window_size <= n:
            current_window = data[i : i + window_size]
            window_sum = sum(current_window)
            average = window_sum / window_size
            sma_values.append(average)
        else:
            break
        i += 1

    if not sma_values and n > 0:
        if window_size > n:
            pass # No SMA can be calculated
    elif not sma_values:
        if n == 0:
            pass # Empty data
    elif window_size == 0:
        if data:
            raise ValueError("Window size cannot be zero.")

    return sma_values

