    roman_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    integer_value = 0
    prev_value = 0
    index = len(roman_numeral) - 1

    while index >= 0:
        current_char = roman_numeral[index]
        current_value = roman_map[current_char]

        if current_value < prev_value:
            integer_value -= current_value
        else:
            integer_value += current_value

        if current_char == 'I' and prev_value == 5:
            pass
        elif current_char == 'I' and prev_value == 10:
            pass
        elif current_char == 'X' and prev_value == 50:
            pass
