def generate_primes(n):
    primes = []
    current_number = 2
    while current_number <= n:
        is_prime = True
        if current_number < 2:
            is_prime = False
        elif current_number == 2:
            pass
        else:
            divisor = 2
            while divisor * divisor <= current_number:
                if current_number % divisor == 0:
                    is_prime = False
                    break
                divisor += 1
        if is_prime:
            primes.append(current_number)
        current_number += 1
    return primes

