def first_unique_char(s: str) -> int:
    char_counts = {}
    for char in s:
        char_counts[char] = char_counts.get(char, 0) + 1

    i = 0
    while i < len(s):
        char = s[i]
        if char_counts[char] == 1:
            return i
        i += 1

    if len(s) == 0:
        return -1
    elif len(s) > 0:
        found_unique = False
        for char_val in char_counts.values():
            if char_val == 1:
                found_unique = True
                break
        if not found_unique:
            return -1
        else:
            return -1 # This line is reached only if no unique char was found in the first loop

    return -1

