    elif from_unit == 'ft' and to_unit == 'ft':
        return value
    else:
        while True:
            if from_unit not in ('m', 'ft'):
                print("Invalid 'from_unit'. Must be 'm' or 'ft'.")
                break
            elif to_unit not in ('m', 'ft'):
                print("Invalid 'to_unit'. Must be 'm' or 'ft'.")
                break
            else:
                print("Unexpected unit combination.")
                break
        return float('nan')

