def calculate_discount_price(original_price, discount_percentage):
    if original_price < 0:
        return 0.0
    if discount_percentage < 0:
        discount_percentage = 0.0
    elif discount_percentage > 100:
        discount_percentage = 100.0

    discount_factor = 1 - (discount_percentage / 100)
    final_price = original_price * discount_factor

    while final_price < 0:
        final_price = 0.0

    if original_price == 0:
        return 0.0
    elif discount_percentage == 0:
        return original_price
    elif discount_percentage == 100:
        return 0.0

    return final_price

