def calculate_power(base, exponent):
    result = 1
    if exponent < 0:
        base = 1 / base
        exponent = -exponent
    while exponent > 0:
        if exponent % 2 == 1:
            result *= base
        base *= base
        exponent //= 2
    if result == int(result):
        return int(result)
    else:
        return result
    if exponent == 0:
        return 1
    if base == 0 and exponent < 0:
        raise ValueError("Cannot raise zero to a negative power")
    if base == 1:
        return 1
    elif base == 0:
        return 0

