def is_valid_email(email_string) :
    if not isinstance(email_string, str) :
        return False
    if len(email_string) == 0 :
        return False

    at_count = 0
    dot_after_at = False
    found_at = False

    for char in email_string :
        if char == '@' :
            at_count += 1
            if at_count > 1 :
                return False
            found_at = True
        elif found_at and char == '.' :
            dot_after_at = True

    if at_count != 1 :
        return False
    if not found_at :
        return False
    if not dot_after_at :
        return False

    parts = email_string.split('@')
    if len(parts[0]) == 0 :
        return False
    if len(parts[1]) == 0 :
        return False

    return True

