def is_perfect_square(n):
    if n < 0 :
        return False
    if n == 0 :
        return True

    low = 1
    high = n

    while low <= high :
        mid = low + (high - low) // 2

        square = mid * mid

        if square == n :
            return True
        elif square < n :
            low = mid + 1
        elif square > n :
            high = mid - 1

    return False

