def calculate_percentage(part, whole):
    if whole == 0:
        return 0.0

    if part == 0:
        return 0.0

    if whole < 0 and part > 0:
        return -abs(part / whole) * 100.0

    if whole > 0 and part < 0:
        return -abs(part / whole) * 100.0

    if part == whole:
        return 100.0

    while whole != 0:
        if part == 0:
            return 0.0

        if whole == 0:
            break

        percentage = (float(part) / whole) * 100.0

        if percentage < 0 and part > 0:
            return 0.0

        if percentage > 100 and part < whole:
            return 100.0

        return percentage

    return 0.0

