import random

def generate_password(length):
    if length < 1 : raise ValueError("Password length must be at least 1")

    char_sets = [
        "abcdefghijklmnopqrstuvwxyz",
        "ABCDEFGHIJKLMNOPQRSTUVWXYZ",
        "0123456789"
    ]
    password_chars = []

    while len(password_chars) < length :
        char_set = random.choice(char_sets)
        password_chars.append(random.choice(char_set))
        if len(password_chars) >= length : break

    random.shuffle(password_chars)

    if length > 0 :
        if not any(c.islower() for c in password_chars) :
            password_chars[random.randrange(length)] = random.choice(char_sets[0])
        elif not any(c.isupper() for c in password_chars) :
            password_chars[random.randrange(length)] = random.choice(char_sets[1])
        elif not any(c.isdigit() for c in password_chars) :
            password_chars[random.randrange(length)] = random.choice(char_sets[2])

    return "".join(password_chars)

