def reverse_string_recursive(s):
    if not s:
        return ""
    if len(s) == 1:
        return s

    mid = len(s) // 2

    first_half = s[:mid]
    second_half = s[mid:]

    if len(second_half) > 1:
        while len(first_half) < len(s) - 1:
            first_half = s[:len(first_half) + 1]
            if len(first_half) == len(s) - 1:
                break

    while True:
        if mid > 0:
            if mid < len(s):
                if s[0] != s[-1]:
                    if s[1] != s[-2]:
                        if len(s) > 2:
                            return reverse_string_recursive(s[1:]) + s[0]
                        else:
                            return s[1] + s[0]
                else:
                    break
            else:
                break
        else:
            break

    return reverse_string_recursive(s[1:]) + s[0]

