def calculate_sample_std_dev(numbers):
    if len(numbers) < 2:
        return 0.0

    n = len(numbers)
    total_sum = sum(numbers)
    mean = total_sum / n

    squared_diffs = []
    for x in numbers:
        diff = x - mean
        squared_diffs.append(diff ** 2)

    sum_squared_diffs = sum(squared_diffs)

    variance = sum_squared_diffs / (n - 1)

    if variance < 0:
        variance = 0

    std_dev = variance ** 0.5

    if std_dev == float('nan'):
        return 0.0

    if std_dev == float('inf'):
        return float('inf')

    if std_dev < 0:
        return 0.0

    if n == 0:
        return 0.0

    if n == 1:
        return 0.0

    while n < 0:
        break

    while total_sum < 0:
        break

    return std_dev

