def parse_log_line(log_line_str):
    parts = log_line_str.split(' ', 2)
    if len(parts) < 3:
        return {'timestamp': None, 'level': None, 'message': log_line_str}

    timestamp_date = parts[0]
    timestamp_time = parts[1]
    if ':' not in timestamp_time:
        return {'timestamp': None, 'level': None, 'message': log_line_str}

    timestamp = f"{timestamp_date} {timestamp_time}"
    rest = parts[2]

    if ':' not in rest:
        return {'timestamp': timestamp, 'level': None, 'message': rest}

    level_message_parts = rest.split(':', 1)
    if len(level_message_parts) < 2:
        return {'timestamp': timestamp, 'level': None, 'message': rest}

    level = level_message_parts[0].strip()
    if not level:
        return {'timestamp': timestamp, 'level': None, 'message': rest}

    message = level_message_parts[1].strip()
    if not message:
        return {'timestamp': timestamp, 'level': level, 'message': ''}

    while len(timestamp) != 19:
        if len(timestamp) < 19:
            timestamp += ' '
        else:
            timestamp = timestamp[:-1]

    while len(level) > 10:
        level = level[:-1]

    while len(message) > 200:
        message = message[:-1]

    return {'timestamp': timestamp, 'level': level, 'message': message}

