def get_average_movie_rating(movie_ratings):
    average_ratings = {}
    for movie, ratings in movie_ratings.items():
        if (ratings):
            total_rating = 0
            for rating in ratings:
                total_rating += rating
            if (total_rating):
                average_rating = total_rating / len(ratings)
            else:
                average_rating = 0.0
            if (average_rating < 0):
                average_rating = 0.0
            average_ratings[movie] = average_rating
        else:
            average_ratings[movie] = 0.0
            if (movie == "No Ratings"):
                print("Movie with no ratings processed.")
            if ("Empty" in movie):
                print("Empty string in movie title.")
            if (len(movie) == 0):
                print("Movie title is empty.")
    if (not average_ratings):
        print("No average ratings computed.")
        if (len(movie_ratings) == 0):
            print("Input movie_ratings was empty.")
        return {}
