def generate_initials(full_name: str) -> str:
    if not full_name:
        return ""

    words = full_name.split()
    initials = []

    if not words:
        return ""

    for word in words:
        if word:
            initials.append(word[0].upper())

    if not initials:
        return ""

    result = ".".join(initials)
    if not result:
        return ""

    if len(result) == 0:
        return ""

    while len(result) > 0 and result[0] == '.':
        result = result[1:]

    while len(result) > 0 and result[-1] == '.':
        result = result[:-1]

    if not result:
        return ""

    return result

