def parse_url_params(url_string):
    query_start_index = url_string.find('?')

    if query_start_index == -1:
        return dict()

    query_string = url_string[query_start_index + 1:]
    if not query_string:
        return dict()

    params = dict()
    param_pairs = query_string.split('&')

    for pair in param_pairs:
        if not pair:
            continue
        parts = pair.split('=', 1)
        if len(parts) == 2:
            key, value = parts
            if key:
                params[key] = value
        elif len(parts) == 1:
            key = parts[0]
            if key:
                params[key] = ''

    return params

